// ===== p237 : la musique des petits jeux — pack « Atrium » de MirMaximus (Freesound, CC0) :
// combats (batailles d'uchronie, duels, commandos, échecs) → « bossfight » ; labyrinthe et galeries → « wicked » ; jeux d'adresse → « chiptune » ;
// et une courte mélodie à la fin d'une partie. Les sons sont décodés seulement quand on en a besoin. =====
const MUS237={b64:{},buf:{},src:null,g:null,next:null};
Object.assign(MUS237.b64,{"arcade": "", "combat": "", "fin": "", "menu": "", "sombre": ""});
function musBuf237(k){if(MUS237.buf[k])return Promise.resolve(MUS237.buf[k]);const c=sndPret();if(!c||!MUS237.b64[k])return Promise.reject();const s=atob(MUS237.b64[k]),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return c.decodeAudioData(u.buffer).then(b=>MUS237.buf[k]=b)}
function musStop237(f){try{const c=SND.ctx,g=MUS237.g,s=MUS237.src;if(g&&c){g.gain.cancelScheduledValues(c.currentTime);g.gain.setValueAtTime(g.gain.value,c.currentTime);g.gain.linearRampToValueAtTime(0,c.currentTime+(f||.8));setTimeout(()=>{try{s.stop()}catch(e){}},(f||.8)*1000+50)}}catch(e){}MUS237.src=null;MUS237.g=null}
function mus237(k,boucle,vol,fin){musStop237(.6);let arr=false;const h={stop(){arr=true;musStop237(.5)}};musBuf237(k).then(b=>{if(arr)return;const c=sndPret();if(!c)return;const s=c.createBufferSource(),g=c.createGain();s.buffer=b;s.loop=!!boucle;g.gain.setValueAtTime(0,c.currentTime);g.gain.linearRampToValueAtTime(vol||.35,c.currentTime+1.2);s.connect(g);g.connect(SND.out);s.start();MUS237.src=s;MUS237.g=g;s.onended=()=>{if(MUS237.src===s){MUS237.src=null;fin&&fin()}}}).catch(()=>{});return h}
// quel jeu s'ouvre : on note le genre avant l'écran d'introduction
[['ouvrirBataille','combat'],['ouvrirDuel','combat'],['ouvrirCommando','combat'],['ouvrirEchecs','combat'],['ouvrirGaleries','sombre'],['ouvrirAventure','arcade'],['ouvrirFPS','combat']].forEach(([f,k])=>{try{const o=window[f];if(typeof o!=='function')return;window[f]=function(){MUS237.next=k;return o.apply(this,arguments)};try{eval(f+'=window[f]')}catch(e){}}catch(e){}});
{const ij=introJeu;introJeu=function(o,go){const k=MUS237.next||'arcade';MUS237.next=null;try{if(typeof SND==='undefined'||SND.on)mus237(k,true,k==='combat'?.32:.3)}catch(e){}return ij.apply(this,arguments)}}
{const fp=finPJ;finPJ=function(){const r=fp.apply(this,arguments);try{if(MUS237.src){musStop237(1.2);setTimeout(()=>mus237('fin',false,.3),900)}}catch(e){}return r}}
try{ANN217.push({g:'Les petits jeux',L:[['Combat','« Bossfight » de MirMaximus (CC0) : batailles, duels, commandos.','mus:combat'],['Le labyrinthe','« Wicked » de MirMaximus (CC0) : les galeries sous la roche.','mus:sombre'],['Jeux d’adresse','« Chiptune melody » de MirMaximus (CC0).','mus:arcade'],['Fin de partie','« Normal melody » de MirMaximus (CC0).','mus:fin'],['Petit air','« Normal melody 2 » de MirMaximus (CC0).','mus:menu']]})}catch(e){}
